import{_ as n,c as s,o as a,a as t}from"./app-olgpHTCG.js";const p="/images/rewrite/perf-reflow-repaint/pipeline-cost.webp",e="/images/rewrite/perf-reflow-repaint/batched-frame.webp",o="/images/rewrite/perf-reflow-repaint/forced-layout.webp",c={},l=t('<h1 id="回流-reflow-与重绘-repaint" tabindex="-1"><a class="header-anchor" href="#回流-reflow-与重绘-repaint"><span>回流（Reflow）与重绘（Repaint）</span></a></h1><h2 id="核心要点" tabindex="-1"><a class="header-anchor" href="#核心要点"><span>核心要点</span></a></h2><ul><li><strong>回流</strong>（也叫重排）：DOM 改动让元素的尺寸或位置变了，浏览器得重新算一遍布局，受牵连的父节点、兄弟节点、子节点都要跟着重算，算完再画。</li><li><strong>重绘</strong>：改动只影响外观（颜色、背景、<code>visibility</code> 等），几何信息不变，浏览器跳过布局，直接重新绘制。</li><li>两者的关系：<strong>回流之后必然重绘，重绘不一定伴随回流</strong>。回流做的事更多，代价更高，但两者都要花性能，能少则少。</li><li>触发回流的操作按代价大致分三类：改几何属性（最贵）、增删移动节点（中等）、读取需要即时计算的布局属性（最隐蔽）。</li><li>浏览器会把样式改动攒成一个队列，等到下一帧渲染时一次性处理，所以连续写四个样式通常只看到一次 Layout、一次 Paint。</li><li>但只要在中途读取 <code>offsetTop</code>、<code>clientWidth</code>、<code>getComputedStyle()</code> 这类值，浏览器就得把队列立刻清空、当场布局，批处理被打断。这叫<strong>强制同步布局</strong>，在循环里反复出现就是<strong>布局抖动</strong>。</li><li>常用的规避办法：把布局读数缓存在变量里、读写分离；用 class 一次性切换多条样式；把要大量修改的 DOM 先「离线」再放回；动画优先用 <code>transform</code> / <code>opacity</code>。</li><li>浏览器自带批处理并不意味着可以不管：自己写的读操作随时会打断它，老旧或低端环境的表现也不可控，养成好的写法才稳。</li></ul><h2 id="先把两个概念分清" tabindex="-1"><a class="header-anchor" href="#先把两个概念分清"><span>先把两个概念分清</span></a></h2><p>浏览器把 DOM 和 CSS 变成屏幕上的像素，要经过样式计算、布局、绘制、合成几个阶段。改动一个样式之后，浏览器要从哪一步开始重跑，取决于这个样式影响到了什么：</p><p><img src="'+p+`" alt="不同属性改动对应的渲染阶段：几何属性触发布局和绘制，外观属性只触发绘制，transform/opacity 只走合成"></p><table><thead><tr><th></th><th>回流（Reflow / 重排）</th><th>重绘（Repaint）</th></tr></thead><tbody><tr><td>触发条件</td><td>元素的几何信息变了：宽高、内外边距、位置、显示与否</td><td>只有外观变了，几何信息不变</td></tr><tr><td>典型属性</td><td><code>width</code>、<code>height</code>、<code>padding</code>、<code>margin</code>、<code>border</code>、<code>top</code>、<code>left</code>、<code>display</code>、<code>font-size</code></td><td><code>color</code>、<code>background-color</code>、<code>visibility</code>、<code>outline</code>、<code>box-shadow</code></td></tr><tr><td>浏览器要做的事</td><td>重新计算布局（波及相关节点）→ 重新绘制</td><td>直接重新绘制该元素</td></tr><tr><td>代价</td><td>高</td><td>相对低</td></tr></tbody></table><p>为什么「回流必然导致重绘，反过来不成立」？因为布局变了，像素一定要重新画；但像素重新画，不代表布局需要重新算。</p><p>这里有一个容易混的点：<code>visibility: hidden</code> 只是让元素看不见，元素仍然占着原来的位置，所以只引起重绘；<code>display: none</code> 则把元素从布局里拿掉，周围的元素会补位，会引起回流。</p><h2 id="哪些操作会引起回流" tabindex="-1"><a class="header-anchor" href="#哪些操作会引起回流"><span>哪些操作会引起回流</span></a></h2><p>重绘的触发条件比较好认：凡是改了样式、又没有动到几何信息的，都属于重绘。真正需要留心的是回流。想减少回流，最根本的办法是从源头上少做会引起回流的操作。按代价从高到低，可以分成三类。</p><h3 id="_1-改几何属性-最贵" tabindex="-1"><a class="header-anchor" href="#_1-改几何属性-最贵"><span>1. 改几何属性：最贵</span></a></h3><p>一个元素的尺寸或位置变了，影响不会只停在它自己身上。父元素可能被撑高，后面的兄弟可能被挤下去，子元素的百分比宽度要重算……一处改动可能连锁地带动一大片节点重新布局。</p><p>会影响几何信息的属性很多，典型的像 <code>height</code>、<code>width</code>、<code>margin</code>、<code>padding</code>、<code>border</code>、<code>left</code>、<code>top</code>、<code>font-size</code>。没必要把完整列表背下来：写样式时改一下属性，看页面上有没有别的东西跟着挪位、跟着变大变小，就能判断它会不会影响布局。多动手试几次，自然会有直觉。实在拿不准，可以打开 Chrome DevTools 的 Performance 面板录一段，看有没有出现 Layout 事件。</p><h3 id="_2-改-dom-结构-中等" tabindex="-1"><a class="header-anchor" href="#_2-改-dom-结构-中等"><span>2. 改 DOM 结构：中等</span></a></h3><p>插入、删除、移动节点都会改变布局树。浏览器布局的大致顺序是从上到下、从左到右，类似对树做一次前序遍历。正常文档流里，一个元素的变化一般不会回头影响排在它前面、已经算好的元素，主要波及的是它后面的内容。所以在列表末尾追加节点，通常比在开头插入受影响的范围小。</p><h3 id="_3-读取需要即时计算的属性-最容易忽略" tabindex="-1"><a class="header-anchor" href="#_3-读取需要即时计算的属性-最容易忽略"><span>3. 读取需要即时计算的属性：最容易忽略</span></a></h3><p>很多人以为只有「写」才会引起回流，其实「读」也会。下面这些属性的值都依赖最新的布局结果：</p><table><thead><tr><th>分组</th><th>属性</th></tr></thead><tbody><tr><td>offset 系列</td><td><code>offsetWidth</code>、<code>offsetHeight</code>、<code>offsetTop</code>、<code>offsetLeft</code></td></tr><tr><td>scroll 系列</td><td><code>scrollWidth</code>、<code>scrollHeight</code>、<code>scrollTop</code>、<code>scrollLeft</code></td></tr><tr><td>client 系列</td><td><code>clientWidth</code>、<code>clientHeight</code>、<code>clientTop</code>、<code>clientLeft</code></td></tr><tr><td>方法</td><td><code>getComputedStyle()</code>（老 IE 里对应 <code>currentStyle</code>）</td></tr></tbody></table><p>浏览器为了返回此刻准确的数值，必须先把还没处理的样式改动算掉，必要时当场做一次布局。同样会带来这个问题的还有 <code>getBoundingClientRect()</code>、<code>innerText</code>、<code>scrollIntoView()</code>、<code>focus()</code>、<code>window.innerWidth</code> / <code>innerHeight</code> 等。</p><blockquote><p>说得更准确一点：读这些属性本身并不一定引起回流。只有在读之前已经有尚未处理、而且会影响布局的改动时，浏览器才不得不提前布局。如果布局本来就是最新的，读取几乎不花什么成本。这一点正是下面「读写分离」能奏效的原因。</p></blockquote><h2 id="浏览器的渲染队列-改四次-只算一次" tabindex="-1"><a class="header-anchor" href="#浏览器的渲染队列-改四次-只算一次"><span>浏览器的渲染队列：改四次，只算一次</span></a></h2><p>先看一个问题。下面给一个弹窗面板连续写四个样式：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> panel <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;.settings-panel&#39;</span><span class="token punctuation">)</span></span>
<span class="line">panel<span class="token punctuation">.</span>style<span class="token punctuation">.</span>width <span class="token operator">=</span> <span class="token string">&#39;320px&#39;</span></span>
<span class="line">panel<span class="token punctuation">.</span>style<span class="token punctuation">.</span>height <span class="token operator">=</span> <span class="token string">&#39;480px&#39;</span></span>
<span class="line">panel<span class="token punctuation">.</span>style<span class="token punctuation">.</span>border <span class="token operator">=</span> <span class="token string">&#39;2px solid #3eaf7c&#39;</span></span>
<span class="line">panel<span class="token punctuation">.</span>style<span class="token punctuation">.</span>color <span class="token operator">=</span> <span class="token string">&#39;#2c3e50&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>浏览器会回流、重绘多少次？</p><p>按前面的分类，很容易得出「<code>width</code>、<code>height</code>、<code>border</code> 各一次回流，<code>color</code> 一次重绘」。但在 Chrome 的 Performance 面板里录一下，主线程上只会看到<strong>一次 Layout 和一次 Paint</strong>：</p><p><img src="`+e+'" alt="四次样式写入在脚本执行期间只被标记，到下一帧统一完成一次样式计算、一次布局和一次绘制"></p><p>原因是浏览器并不会每写一次样式就立刻重新布局。它把这些改动先记下来，把相关节点标记为「需要重新计算」，放进一个待处理的队列（常被称为 flush 队列或渲染队列）。等到下一帧真正要出画面、队列里积累的改动足够多，或者遇到不得不马上给出结果的时刻，再一次性处理。脚本里改了四次，最后只结算一次。</p><p>问题出在「不得不马上给出结果」这种情况上。前面第 3 类里那些需要即时计算的属性，一旦在队列里还有改动时被读取，浏览器为了给出准确值，就只能提前清空队列、立刻布局。这就是<strong>强制同步布局</strong>（Forced Synchronous Layout）。如果在循环里写一次、读一次、再写一次，每一轮都会强制布局一次，这种情况叫<strong>布局抖动</strong>（Layout Thrashing）：</p><p><img src="'+o+`" alt="先写后读的循环每一轮都会触发一次强制布局，而先读、在 JS 中计算、最后一次性写入只在帧末布局一次"></p><p>在 Performance 面板里，强制同步布局的 Layout 事件会带一个红色角标，并提示「Forced reflow is a likely performance bottleneck」，点进去能看到是哪一行 JS 触发的。</p><h2 id="怎么减少回流和重绘" tabindex="-1"><a class="header-anchor" href="#怎么减少回流和重绘"><span>怎么减少回流和重绘</span></a></h2><p>有些操作绕不开，那就想办法让它们发生的次数少一点、范围小一点。</p><h3 id="_1-把布局读数存进变量-读和写分开" tabindex="-1"><a class="header-anchor" href="#_1-把布局读数存进变量-读和写分开"><span>1. 把布局读数存进变量，读和写分开</span></a></h3><p>场景：让一个提示气泡沿对角线移动 8 步，每步向右 12px、向下 6px。直觉的写法是每一步都读当前位置、再写新位置：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token doctype"><span class="token punctuation">&lt;!</span><span class="token doctype-tag">DOCTYPE</span> <span class="token name">html</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span> <span class="token attr-name">lang</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>zh-CN<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">charset</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>UTF-8<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span>气泡移动：反例<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>style</span><span class="token punctuation">&gt;</span></span><span class="token style"><span class="token language-css"></span>
<span class="line">    <span class="token selector">.bubble</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">position</span><span class="token punctuation">:</span> absolute<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">width</span><span class="token punctuation">:</span> 140px<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">padding</span><span class="token punctuation">:</span> 8px 12px<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">border-radius</span><span class="token punctuation">:</span> 6px<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">background</span><span class="token punctuation">:</span> #2c3e50<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">color</span><span class="token punctuation">:</span> #fff<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>style</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>bubble<span class="token punctuation">&quot;</span></span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>bubble<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>新消息<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"></span>
<span class="line">    <span class="token keyword">const</span> bubble <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;bubble&#39;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> step <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> step <span class="token operator">&lt;</span> <span class="token number">8</span><span class="token punctuation">;</span> step<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">// 每一轮先读再写，下一轮读的时候上一轮的写还没结算</span></span>
<span class="line">      bubble<span class="token punctuation">.</span>style<span class="token punctuation">.</span>left <span class="token operator">=</span> bubble<span class="token punctuation">.</span>offsetLeft <span class="token operator">+</span> <span class="token number">12</span> <span class="token operator">+</span> <span class="token string">&#39;px&#39;</span></span>
<span class="line">      bubble<span class="token punctuation">.</span>style<span class="token punctuation">.</span>top <span class="token operator">=</span> bubble<span class="token punctuation">.</span>offsetTop <span class="token operator">+</span> <span class="token number">6</span> <span class="token operator">+</span> <span class="token string">&#39;px&#39;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这段代码每一轮都要读布局属性，而上一次写入还没结算，于是每一次读都是一次强制布局。改法是只读一次，把计算放在 JS 变量里完成，最后一次性写回 DOM：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> bubble <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;bubble&#39;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 只读一次布局信息</span></span>
<span class="line"><span class="token keyword">let</span> nextX <span class="token operator">=</span> bubble<span class="token punctuation">.</span>offsetLeft</span>
<span class="line"><span class="token keyword">let</span> nextY <span class="token operator">=</span> bubble<span class="token punctuation">.</span>offsetTop</span>
<span class="line"></span>
<span class="line"><span class="token comment">// 纯 JS 计算，不碰 DOM</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> step <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> step <span class="token operator">&lt;</span> <span class="token number">8</span><span class="token punctuation">;</span> step<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  nextX <span class="token operator">+=</span> <span class="token number">12</span></span>
<span class="line">  nextY <span class="token operator">+=</span> <span class="token number">6</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 统一写回，交给浏览器在下一帧一起处理</span></span>
<span class="line">bubble<span class="token punctuation">.</span>style<span class="token punctuation">.</span>left <span class="token operator">=</span> nextX <span class="token operator">+</span> <span class="token string">&#39;px&#39;</span></span>
<span class="line">bubble<span class="token punctuation">.</span>style<span class="token punctuation">.</span>top <span class="token operator">=</span> nextY <span class="token operator">+</span> <span class="token string">&#39;px&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用 node 写一个极简模拟就能看出差距：写样式只把节点标为「脏」，读布局属性时如果节点是脏的，就计一次强制布局。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">function</span> <span class="token function">createFakeNode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">let</span> dirty <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line">  <span class="token keyword">const</span> stats <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">forcedLayouts</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">const</span> box <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">const</span> style <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Proxy</span><span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">set</span><span class="token punctuation">(</span>target<span class="token punctuation">,</span> key<span class="token punctuation">,</span> value<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      target<span class="token punctuation">[</span>key<span class="token punctuation">]</span> <span class="token operator">=</span> value</span>
<span class="line">      dirty <span class="token operator">=</span> <span class="token boolean">true</span>            <span class="token comment">// 只记账，不计算</span></span>
<span class="line">      <span class="token keyword">return</span> <span class="token boolean">true</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">function</span> <span class="token function">flush</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>dirty<span class="token punctuation">)</span> <span class="token keyword">return</span></span>
<span class="line">    box<span class="token punctuation">.</span>x <span class="token operator">=</span> <span class="token function">parseFloat</span><span class="token punctuation">(</span>style<span class="token punctuation">.</span>left<span class="token punctuation">)</span> <span class="token operator">||</span> <span class="token number">0</span></span>
<span class="line">    box<span class="token punctuation">.</span>y <span class="token operator">=</span> <span class="token function">parseFloat</span><span class="token punctuation">(</span>style<span class="token punctuation">.</span>top<span class="token punctuation">)</span> <span class="token operator">||</span> <span class="token number">0</span></span>
<span class="line">    dirty <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">    style<span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">get</span> <span class="token function">offsetLeft</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>dirty<span class="token punctuation">)</span> stats<span class="token punctuation">.</span>forcedLayouts<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token function">flush</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> box<span class="token punctuation">.</span>x <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">get</span> <span class="token function">offsetTop</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token punctuation">{</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>dirty<span class="token punctuation">)</span> stats<span class="token punctuation">.</span>forcedLayouts<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token function">flush</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> box<span class="token punctuation">.</span>y <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    stats<span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 反例：循环里先读后写</span></span>
<span class="line"><span class="token keyword">const</span> bubbleA <span class="token operator">=</span> <span class="token function">createFakeNode</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> step <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> step <span class="token operator">&lt;</span> <span class="token number">8</span><span class="token punctuation">;</span> step<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  bubbleA<span class="token punctuation">.</span>style<span class="token punctuation">.</span>left <span class="token operator">=</span> bubbleA<span class="token punctuation">.</span>offsetLeft <span class="token operator">+</span> <span class="token number">12</span> <span class="token operator">+</span> <span class="token string">&#39;px&#39;</span></span>
<span class="line">  bubbleA<span class="token punctuation">.</span>style<span class="token punctuation">.</span>top  <span class="token operator">=</span> bubbleA<span class="token punctuation">.</span>offsetTop  <span class="token operator">+</span> <span class="token number">6</span>  <span class="token operator">+</span> <span class="token string">&#39;px&#39;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 正例：只读一次，变量里算完，最后写一次</span></span>
<span class="line"><span class="token keyword">const</span> bubbleB <span class="token operator">=</span> <span class="token function">createFakeNode</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">let</span> nextX <span class="token operator">=</span> bubbleB<span class="token punctuation">.</span>offsetLeft</span>
<span class="line"><span class="token keyword">let</span> nextY <span class="token operator">=</span> bubbleB<span class="token punctuation">.</span>offsetTop</span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> step <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> step <span class="token operator">&lt;</span> <span class="token number">8</span><span class="token punctuation">;</span> step<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  nextX <span class="token operator">+=</span> <span class="token number">12</span></span>
<span class="line">  nextY <span class="token operator">+=</span> <span class="token number">6</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">bubbleB<span class="token punctuation">.</span>style<span class="token punctuation">.</span>left <span class="token operator">=</span> nextX <span class="token operator">+</span> <span class="token string">&#39;px&#39;</span></span>
<span class="line">bubbleB<span class="token punctuation">.</span>style<span class="token punctuation">.</span>top  <span class="token operator">=</span> nextY <span class="token operator">+</span> <span class="token string">&#39;px&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> thrashCount <span class="token operator">=</span> bubbleA<span class="token punctuation">.</span>stats<span class="token punctuation">.</span>forcedLayouts</span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;反例 强制布局次数:&#39;</span><span class="token punctuation">,</span> thrashCount<span class="token punctuation">)</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;正例 强制布局次数:&#39;</span><span class="token punctuation">,</span> bubbleB<span class="token punctuation">.</span>stats<span class="token punctuation">.</span>forcedLayouts<span class="token punctuation">,</span> <span class="token string">&#39;最终位置:&#39;</span><span class="token punctuation">,</span> nextX<span class="token punctuation">,</span> nextY<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 反例 强制布局次数: 15</span></span>
<span class="line"><span class="token comment">// 正例 强制布局次数: 0 最终位置: 96 48</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>反例里除了第一次读取，每次读都撞上了还没结算的写入，8 轮共 16 次读取，有 15 次是强制布局；正例一次都没有，最终位置完全相同。</p><p>当多个组件分散在各处、各自都要「读一下再写一下」时，可以把读和写分别排进队列，在同一帧里先统一读、再统一写（<a href="https://github.com/wilsonpage/fastdom" target="_blank" rel="noopener noreferrer">fastdom</a> 这类库就是这么做的）。下面是一个能在 node 里跑的最小版本：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// node 里没有 requestAnimationFrame，用 setTimeout 模拟一帧</span></span>
<span class="line"><span class="token keyword">const</span> raf <span class="token operator">=</span> globalThis<span class="token punctuation">.</span>requestAnimationFrame <span class="token operator">||</span> <span class="token punctuation">(</span><span class="token parameter">cb</span> <span class="token operator">=&gt;</span> <span class="token function">setTimeout</span><span class="token punctuation">(</span>cb<span class="token punctuation">,</span> <span class="token number">16</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> reads <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">const</span> writes <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">let</span> scheduled <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">flushFrame</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 先执行所有读，再执行所有写，读写不会交错</span></span>
<span class="line">  reads<span class="token punctuation">.</span><span class="token function">splice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token parameter">job</span> <span class="token operator">=&gt;</span> <span class="token function">job</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  writes<span class="token punctuation">.</span><span class="token function">splice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token parameter">job</span> <span class="token operator">=&gt;</span> <span class="token function">job</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  scheduled <span class="token operator">=</span> <span class="token boolean">false</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">schedule</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>scheduled<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    scheduled <span class="token operator">=</span> <span class="token boolean">true</span></span>
<span class="line">    <span class="token function">raf</span><span class="token punctuation">(</span>flushFrame<span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">measure</span> <span class="token operator">=</span> <span class="token parameter">job</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> reads<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>job<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token function">schedule</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">mutate</span>  <span class="token operator">=</span> <span class="token parameter">job</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span> writes<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>job<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token function">schedule</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">const</span> log <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> name <span class="token keyword">of</span> <span class="token punctuation">[</span><span class="token string">&#39;header&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;sidebar&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;footer&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">measure</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> log<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">读 </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>name<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token function">mutate</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> log<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">写 </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>name<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>log<span class="token punctuation">.</span><span class="token function">join</span><span class="token punctuation">(</span><span class="token string">&#39; → &#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 读 header → 读 sidebar → 读 footer → 写 header → 写 sidebar → 写 footer</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三个组件的调用顺序是读写交替，实际执行变成了先读完再写完，中间不会出现强制布局。</p><h3 id="_2-不要一条一条改样式-用-class-一次切换" tabindex="-1"><a class="header-anchor" href="#_2-不要一条一条改样式-用-class-一次切换"><span>2. 不要一条一条改样式，用 class 一次切换</span></a></h3><p>场景：消息提示条从隐藏状态变成展示状态，需要改尺寸、边框、字体颜色。逐条写 <code>style</code>：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> toast <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;toast&#39;</span><span class="token punctuation">)</span></span>
<span class="line">toast<span class="token punctuation">.</span>style<span class="token punctuation">.</span>width <span class="token operator">=</span> <span class="token string">&#39;280px&#39;</span></span>
<span class="line">toast<span class="token punctuation">.</span>style<span class="token punctuation">.</span>padding <span class="token operator">=</span> <span class="token string">&#39;12px 16px&#39;</span></span>
<span class="line">toast<span class="token punctuation">.</span>style<span class="token punctuation">.</span>borderLeft <span class="token operator">=</span> <span class="token string">&#39;4px solid #3eaf7c&#39;</span></span>
<span class="line">toast<span class="token punctuation">.</span>style<span class="token punctuation">.</span>color <span class="token operator">=</span> <span class="token string">&#39;#1f6f4a&#39;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>把这组样式收进一个 class，JS 里只切换类名：</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html" data-title="html"><pre class="language-html"><code><span class="line"><span class="token doctype"><span class="token punctuation">&lt;!</span><span class="token doctype-tag">DOCTYPE</span> <span class="token name">html</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span> <span class="token attr-name">lang</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>zh-CN<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">charset</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>UTF-8<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span>提示条：用 class 合并样式<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>style</span><span class="token punctuation">&gt;</span></span><span class="token style"><span class="token language-css"></span>
<span class="line">    <span class="token selector">.toast--shown</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">width</span><span class="token punctuation">:</span> 280px<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">padding</span><span class="token punctuation">:</span> 12px 16px<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">border-left</span><span class="token punctuation">:</span> 4px solid #3eaf7c<span class="token punctuation">;</span></span>
<span class="line">      <span class="token property">color</span><span class="token punctuation">:</span> #1f6f4a<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>style</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>toast<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>保存成功<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"></span>
<span class="line">    document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;toast&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>classList<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token string">&#39;toast--shown&#39;</span><span class="token punctuation">)</span></span>
<span class="line">  </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>逐条修改时，每一条都会单独更新一次样式，在没有批处理的环境里就意味着每条都可能引起一次回流和重绘；换成 class 之后，所有改动随一次类名变化一起提交。额外的好处是样式回到了 CSS 里，结构和表现分开，更好维护。</p><p>如果样式值是运行时算出来的、没法提前写进 class，可以用 <code>el.style.cssText += &#39;; width: 280px; padding: 12px 16px&#39;</code> 一次写入多条。</p><h3 id="_3-把-dom-先「离线」-改完再放回去" tabindex="-1"><a class="header-anchor" href="#_3-把-dom-先「离线」-改完再放回去"><span>3. 把 DOM 先「离线」，改完再放回去</span></a></h3><p>前面说的回流和重绘，前提都是元素正显示在页面上。如果先给元素设上 <code>display: none</code>，它就不参与布局了，之后对它做多少修改都不会引起回流和重绘。等全部改完再显示出来，这种做法叫 DOM 离线化。</p><p>比如要对一个排行榜面板做一长串调整：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> board <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;leaderboard&#39;</span><span class="token punctuation">)</span></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>width <span class="token operator">=</span> <span class="token string">&#39;360px&#39;</span></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>padding <span class="token operator">=</span> <span class="token string">&#39;16px&#39;</span></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>borderTop <span class="token operator">=</span> <span class="token string">&#39;3px solid #3eaf7c&#39;</span></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>fontSize <span class="token operator">=</span> <span class="token string">&#39;15px&#39;</span></span>
<span class="line"><span class="token comment">// ……后面还有几十处类似的修改</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>离线化之后：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token keyword">const</span> board <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;leaderboard&#39;</span><span class="token punctuation">)</span></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>display <span class="token operator">=</span> <span class="token string">&#39;none&#39;</span>      <span class="token comment">// 拿下来：触发一次回流</span></span>
<span class="line"></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>width <span class="token operator">=</span> <span class="token string">&#39;360px&#39;</span></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>padding <span class="token operator">=</span> <span class="token string">&#39;16px&#39;</span></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>borderTop <span class="token operator">=</span> <span class="token string">&#39;3px solid #3eaf7c&#39;</span></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>fontSize <span class="token operator">=</span> <span class="token string">&#39;15px&#39;</span></span>
<span class="line"><span class="token comment">// ……后面还有几十处类似的修改，都不会引起回流和重绘</span></span>
<span class="line"></span>
<span class="line">board<span class="token punctuation">.</span>style<span class="token punctuation">.</span>display <span class="token operator">=</span> <span class="token string">&#39;block&#39;</span>     <span class="token comment">// 放回去：再触发一次回流</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>隐藏和显示本身各会引起一次回流，这是不是得不偿失？要看改动量。只改两三处的时候，离线化确实没什么优势；改动一多，元素离线期间的每一步都很便宜，付出的这两次回流就很划算了。</p><p>还有两种离线的做法，在批量插入节点时更常用：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js" data-title="js"><pre class="language-javascript"><code><span class="line"><span class="token comment">// 做法一：在 DocumentFragment 里组装好，一次性插入</span></span>
<span class="line"><span class="token keyword">const</span> list <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;rank-list&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">const</span> fragment <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createDocumentFragment</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">const</span> player <span class="token keyword">of</span> players<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> li <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">createElement</span><span class="token punctuation">(</span><span class="token string">&#39;li&#39;</span><span class="token punctuation">)</span></span>
<span class="line">  li<span class="token punctuation">.</span>textContent <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>player<span class="token punctuation">.</span>name<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">　</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>player<span class="token punctuation">.</span>score<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> 分</span><span class="token template-punctuation string">\`</span></span></span>
<span class="line">  fragment<span class="token punctuation">.</span><span class="token function">appendChild</span><span class="token punctuation">(</span>li<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">list<span class="token punctuation">.</span><span class="token function">appendChild</span><span class="token punctuation">(</span>fragment<span class="token punctuation">)</span>   <span class="token comment">// 只在这里动一次真实 DOM</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 做法二：克隆一份离线副本，改完整体替换</span></span>
<span class="line"><span class="token keyword">const</span> draft <span class="token operator">=</span> list<span class="token punctuation">.</span><span class="token function">cloneNode</span><span class="token punctuation">(</span><span class="token boolean">true</span><span class="token punctuation">)</span></span>
<span class="line">draft<span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;li&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token parameter">li</span> <span class="token operator">=&gt;</span> li<span class="token punctuation">.</span>classList<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token string">&#39;rank-item&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">list<span class="token punctuation">.</span><span class="token function">replaceWith</span><span class="token punctuation">(</span>draft<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>另外要注意：离线期间不要去读这个元素的布局属性，<code>display: none</code> 的元素读出来的 <code>offsetWidth</code> 等都是 0。</p><h3 id="_4-其他值得知道的做法" tabindex="-1"><a class="header-anchor" href="#_4-其他值得知道的做法"><span>4. 其他值得知道的做法</span></a></h3><ul><li><strong>动画用 <code>transform</code> 和 <code>opacity</code></strong>：位移用 <code>transform: translate()</code> 代替改 <code>top</code> / <code>left</code>，渐隐用 <code>opacity</code>。元素在独立的合成图层上时，这两个属性只需要合成，不回流也不重绘。可以提前用 <code>will-change: transform</code> 提示浏览器，但不要滥用，每个图层都占内存。</li><li><strong>让动画元素脱离文档流</strong>：需要频繁变化尺寸的元素设成 <code>position: absolute</code> 或 <code>fixed</code>，它的变化就不会挤动周围的布局，回流的范围小得多。</li><li><strong>用 <code>contain</code> 圈定影响范围</strong>：<code>contain: layout</code> 或 <code>contain: content</code> 告诉浏览器这个元素内部的变化不会影响外部，布局可以只在局部重算。长列表里离屏的部分还可以用 <code>content-visibility: auto</code> 直接跳过渲染。</li><li><strong>避免 table 布局</strong>：表格里一个单元格的变化可能导致整张表重新计算宽度。</li><li><strong>用 <code>requestAnimationFrame</code> 安排写操作</strong>：把视觉相关的改动放进 rAF 回调，和浏览器的帧节奏对齐，不会在一帧里重复布局。</li></ul><h2 id="浏览器已经会批处理-为什么还要自己操心" tabindex="-1"><a class="header-anchor" href="#浏览器已经会批处理-为什么还要自己操心"><span>浏览器已经会批处理，为什么还要自己操心</span></a></h2><p>既然浏览器会把改动攒起来统一处理，开发者为什么还要在意这些细节？有两个原因。</p><p>第一，批处理很脆弱。只要自己的代码在中间读了一次布局属性，攒起来的队列就得当场清空。很多强制同步布局藏在不起眼的地方，比如一个工具函数里顺手调了 <code>getBoundingClientRect()</code>，或者第三方组件在循环里读 <code>offsetHeight</code>。浏览器的优化管不到这些情况，只有自己避开。</p><p>第二，不能假设每个用户的环境都一样。上面的性能图来自 Chrome，现代主流浏览器都有类似的批处理机制，但早年的浏览器（比如老版本 IE）在这方面就差得多，低端设备上同样的布局开销也会被放大好几倍。用户用什么设备、什么浏览器，我们控制不了。如果全靠浏览器兜底，同一个页面在不同环境下的流畅度可能差别很大。从写法上避免多余的回流和重绘，才是不依赖环境的做法。</p><h2 id="面试速答模板" tabindex="-1"><a class="header-anchor" href="#面试速答模板"><span>面试速答模板</span></a></h2><blockquote><p>回流是 DOM 改动影响了元素的几何信息，比如宽高、位置、显示隐藏、增删节点，浏览器要重新计算布局，而且会波及相关的父子和兄弟节点，算完还要重绘；重绘是只改了颜色、背景、<code>visibility</code> 这类外观，跳过布局直接重画。所以回流一定引起重绘，重绘不一定引起回流，回流代价更大。除了改几何属性和改 DOM 结构，读取 <code>offsetTop</code>、<code>scrollTop</code>、<code>clientWidth</code>、<code>getComputedStyle()</code>、<code>getBoundingClientRect()</code> 这类需要即时计算的值也会触发回流。浏览器平时会把样式改动放进队列，到下一帧统一做一次布局和绘制，但读这些属性会让它提前清空队列、强制同步布局，在循环里读写交替就会造成布局抖动。优化手段有：缓存布局读数、读写分离（可以借助 <code>requestAnimationFrame</code> 或 fastdom）；用 class 或 <code>cssText</code> 一次性改多条样式；用 <code>display: none</code>、DocumentFragment 或 <code>cloneNode</code> 让 DOM 离线后批量修改；动画用 <code>transform</code> 和 <code>opacity</code>，频繁变化的元素脱离文档流，必要时用 <code>contain</code> 限定影响范围。</p></blockquote>`,69),i=[l];function u(r,d){return a(),s("div",null,i)}const m=n(c,[["render",u],["__file","13-渲染篇-5-最后一击——回流-Reflow-与重绘-Repaint.html.vue"]]),v=JSON.parse('{"path":"/%E8%BF%9B%E9%98%B6%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96/13-%E6%B8%B2%E6%9F%93%E7%AF%87-5-%E6%9C%80%E5%90%8E%E4%B8%80%E5%87%BB%E2%80%94%E2%80%94%E5%9B%9E%E6%B5%81-Reflow-%E4%B8%8E%E9%87%8D%E7%BB%98-Repaint.html","title":"渲染篇 最后一击——回流 Reflow 与重绘 Repaint","lang":"zh-CN","frontmatter":{"title":"渲染篇 最后一击——回流 Reflow 与重绘 Repaint","description":"回流（Reflow）与重绘（Repaint） 核心要点 回流（也叫重排）：DOM 改动让元素的尺寸或位置变了，浏览器得重新算一遍布局，受牵连的父节点、兄弟节点、子节点都要跟着重算，算完再画。 重绘：改动只影响外观（颜色、背景、visibility 等），几何信息不变，浏览器跳过布局，直接重新绘制。 两者的关系：回流之后必然重绘，重绘不一定伴随回流。回流...","head":[["meta",{"property":"og:url","content":"https://interview.leeguoo.com/%E8%BF%9B%E9%98%B6%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96/13-%E6%B8%B2%E6%9F%93%E7%AF%87-5-%E6%9C%80%E5%90%8E%E4%B8%80%E5%87%BB%E2%80%94%E2%80%94%E5%9B%9E%E6%B5%81-Reflow-%E4%B8%8E%E9%87%8D%E7%BB%98-Repaint.html"}],["meta",{"property":"og:site_name","content":"前端面试题集锦"}],["meta",{"property":"og:title","content":"渲染篇 最后一击——回流 Reflow 与重绘 Repaint"}],["meta",{"property":"og:description","content":"回流（Reflow）与重绘（Repaint） 核心要点 回流（也叫重排）：DOM 改动让元素的尺寸或位置变了，浏览器得重新算一遍布局，受牵连的父节点、兄弟节点、子节点都要跟着重算，算完再画。 重绘：改动只影响外观（颜色、背景、visibility 等），几何信息不变，浏览器跳过布局，直接重新绘制。 两者的关系：回流之后必然重绘，重绘不一定伴随回流。回流..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://interview.leeguoo.com/images/rewrite/perf-reflow-repaint/pipeline-cost.webp"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-02T11:46:12.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-02T11:46:12.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"渲染篇 最后一击——回流 Reflow 与重绘 Repaint\\",\\"image\\":[\\"https://interview.leeguoo.com/images/rewrite/perf-reflow-repaint/pipeline-cost.webp\\",\\"https://interview.leeguoo.com/images/rewrite/perf-reflow-repaint/batched-frame.webp\\",\\"https://interview.leeguoo.com/images/rewrite/perf-reflow-repaint/forced-layout.webp\\"],\\"dateModified\\":\\"2026-10-02T11:46:12.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":2,"title":"核心要点","slug":"核心要点","link":"#核心要点","children":[]},{"level":2,"title":"先把两个概念分清","slug":"先把两个概念分清","link":"#先把两个概念分清","children":[]},{"level":2,"title":"哪些操作会引起回流","slug":"哪些操作会引起回流","link":"#哪些操作会引起回流","children":[{"level":3,"title":"1. 改几何属性：最贵","slug":"_1-改几何属性-最贵","link":"#_1-改几何属性-最贵","children":[]},{"level":3,"title":"2. 改 DOM 结构：中等","slug":"_2-改-dom-结构-中等","link":"#_2-改-dom-结构-中等","children":[]},{"level":3,"title":"3. 读取需要即时计算的属性：最容易忽略","slug":"_3-读取需要即时计算的属性-最容易忽略","link":"#_3-读取需要即时计算的属性-最容易忽略","children":[]}]},{"level":2,"title":"浏览器的渲染队列：改四次，只算一次","slug":"浏览器的渲染队列-改四次-只算一次","link":"#浏览器的渲染队列-改四次-只算一次","children":[]},{"level":2,"title":"怎么减少回流和重绘","slug":"怎么减少回流和重绘","link":"#怎么减少回流和重绘","children":[{"level":3,"title":"1. 把布局读数存进变量，读和写分开","slug":"_1-把布局读数存进变量-读和写分开","link":"#_1-把布局读数存进变量-读和写分开","children":[]},{"level":3,"title":"2. 不要一条一条改样式，用 class 一次切换","slug":"_2-不要一条一条改样式-用-class-一次切换","link":"#_2-不要一条一条改样式-用-class-一次切换","children":[]},{"level":3,"title":"3. 把 DOM 先「离线」，改完再放回去","slug":"_3-把-dom-先「离线」-改完再放回去","link":"#_3-把-dom-先「离线」-改完再放回去","children":[]},{"level":3,"title":"4. 其他值得知道的做法","slug":"_4-其他值得知道的做法","link":"#_4-其他值得知道的做法","children":[]}]},{"level":2,"title":"浏览器已经会批处理，为什么还要自己操心","slug":"浏览器已经会批处理-为什么还要自己操心","link":"#浏览器已经会批处理-为什么还要自己操心","children":[]},{"level":2,"title":"面试速答模板","slug":"面试速答模板","link":"#面试速答模板","children":[]}],"git":{"updatedTime":1790941572000,"contributors":[{"name":"leeguooooo","email":"guoli@zhihu.com","commits":4}]},"autoDesc":true,"filePathRelative":"进阶性能优化/13-渲染篇-5-最后一击——回流-Reflow-与重绘-Repaint.md","excerpt":"\\n<h2>核心要点</h2>\\n<ul>\\n<li><strong>回流</strong>（也叫重排）：DOM 改动让元素的尺寸或位置变了，浏览器得重新算一遍布局，受牵连的父节点、兄弟节点、子节点都要跟着重算，算完再画。</li>\\n<li><strong>重绘</strong>：改动只影响外观（颜色、背景、<code>visibility</code> 等），几何信息不变，浏览器跳过布局，直接重新绘制。</li>\\n<li>两者的关系：<strong>回流之后必然重绘，重绘不一定伴随回流</strong>。回流做的事更多，代价更高，但两者都要花性能，能少则少。</li>\\n<li>触发回流的操作按代价大致分三类：改几何属性（最贵）、增删移动节点（中等）、读取需要即时计算的布局属性（最隐蔽）。</li>\\n<li>浏览器会把样式改动攒成一个队列，等到下一帧渲染时一次性处理，所以连续写四个样式通常只看到一次 Layout、一次 Paint。</li>\\n<li>但只要在中途读取 <code>offsetTop</code>、<code>clientWidth</code>、<code>getComputedStyle()</code> 这类值，浏览器就得把队列立刻清空、当场布局，批处理被打断。这叫<strong>强制同步布局</strong>，在循环里反复出现就是<strong>布局抖动</strong>。</li>\\n<li>常用的规避办法：把布局读数缓存在变量里、读写分离；用 class 一次性切换多条样式；把要大量修改的 DOM 先「离线」再放回；动画优先用 <code>transform</code> / <code>opacity</code>。</li>\\n<li>浏览器自带批处理并不意味着可以不管：自己写的读操作随时会打断它，老旧或低端环境的表现也不可控，养成好的写法才稳。</li>\\n</ul>"}');export{m as comp,v as data};
